<div><a href="{{route('orders.index')}}" class="text-sm text-violet-700">← Pedidos</a><div class="mt-3 flex flex-wrap justify-between"><div><h1 class="text-3xl font-black">{{$order->number}}</h1><p>{{$order->customer_name}} · {{$order->customer_email}}</p></div><div><b>{{$order->status->label()}}</b><p>{{$order->payment_status->label()}}</p></div></div>@if($errors->any())<p class="mt-4 rounded-xl bg-red-50 p-3 text-red-700">{{$errors->first()}}</p>@endif<div class="mt-6 grid gap-5 lg:grid-cols-3"><section class="rounded-2xl border bg-white p-5 lg:col-span-2"><h2 class="font-bold">Itens</h2>@foreach($order->items as $item)<div class="flex justify-between border-b py-3"><span>{{$item->quantity}}× {{$item->product_name}} {{$item->variant_name}}</span><b>R$ {{number_format($item->subtotal/100,2,',','.')}}</b></div>@endforeach<div class="mt-4 flex justify-between text-xl"><span>Total</span><b>R$ {{number_format($order->total/100,2,',','.')}}</b></div></section><aside class="space-y-4"><div class="rounded-2xl border bg-white p-5"><h2 class="font-bold">Ações</h2><select wire:model="nextStatus" class="mt-3 w-full"><option value="">Novo status</option>@foreach(\App\Enums\OrderStatus::cases() as $s)<option value="{{$s->value}}">{{$s->label()}}</option>@endforeach</select><textarea wire:model="comment" class="mt-3 w-full" placeholder="Comentário"></textarea><button wire:click="transition" class="mt-3 w-full rounded-xl bg-slate-900 p-3 text-white">Atualizar status</button>@if($order->payment_status===\App\Enums\PaymentStatus::Pending)<button wire:click="markPaid" class="mt-2 w-full rounded-xl border p-3">Marcar como pago</button>@endif@if(in_array($order->status,[\App\Enums\OrderStatus::Pending,\App\Enums\OrderStatus::Confirmed],true))<button wire:click="cancel" wire:confirm="Cancelar e devolver estoque?" class="mt-2 w-full text-red-600">Cancelar pedido</button>@endif</div><div class="rounded-2xl border bg-white p-5"><label class="font-bold">Rastreio<input wire:model="trackingCode" class="mt-2 w-full"></label><button wire:click="saveTracking" class="mt-2 text-violet-700">Salvar código</button></div></aside></div><section class="mt-5 rounded-2xl border bg-white p-5"><h2 class="font-bold">Histórico</h2>@foreach($order->histories as $history)<div class="border-b py-3"><b>{{$history->to_status}}</b> · {{$history->created_at->format('d/m/Y H:i')}}<p class="text-sm text-slate-500">{{$history->comment}}</p></div>@endforeach</section></div>
